INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('617e9247-45b1-47d6-b787-b309b5b7d02f', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 3, 'A Escuta do Coração', NULL, '{"intro": "A ora\u00e7\u00e3o m\u00edstica \u00e9 mais recep\u00e7\u00e3o do que emiss\u00e3o.", "prayer": "Deixe que Ele fale no centro do seu ser.", "practice": "Passe 10 minutos apenas ouvindo o som ambiente.", "reflection": "N\u00e3o fale, escute. O Mestre est\u00e1 na sala.", "journal_prompt": "Qual foi a \u00faltima coisa que Ele lhe sussurrou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('8bb7e628-8e0b-497e-b8f0-dc9cd2f567a9', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 4, 'O Fogo que Consome', NULL, '{"intro": "A purifica\u00e7\u00e3o d\u00f3i, mas \u00e9 ela que nos torna transparentes.", "prayer": "Pe\u00e7a para ser consumido pelo Amor.", "practice": "Agrade\u00e7a por uma dificuldade que te amadureceu.", "reflection": "O amor de Deus n\u00e3o \u00e9 um sentimento, \u00e9 um fogo purificador.", "journal_prompt": "O que em voc\u00ea ainda resiste ao fogo?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('dfbe9731-29a5-4797-9be6-9b711ac4af1a', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 5, 'A Nuvem do Não-Saber', NULL, '{"intro": "A mente racional tem limites que a f\u00e9 deve ultrapassar.", "prayer": "Confie no escuro da f\u00e9.", "practice": "Abandone hoje o controle sobre uma situa\u00e7\u00e3o incerta.", "reflection": "Para conhec\u00ea-Lo verdadeiramente, \u00e9 preciso desaprender tudo.", "journal_prompt": "Voc\u00ea consegue amar o que n\u00e3o entende?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('d782d01e-c40c-4e75-80ff-8a3d3467f818', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 6, 'A União Íntima', NULL, '{"intro": "A m\u00edstica \u00e9 o fim da separa\u00e7\u00e3o entre o Criador e a criatura.", "prayer": "Sinta a uni\u00e3o profunda em cada respira\u00e7\u00e3o.", "practice": "Aja hoje como se Ele estivesse fisicamente ao seu lado.", "reflection": "Eu nele e Ele em mim: um s\u00f3 cora\u00e7\u00e3o.", "journal_prompt": "Onde termina voc\u00ea e come\u00e7a Ele?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('4bae9977-bcbf-4363-8993-5c79976aa325', 'b25b02f4-0533-483f-9a7b-c2e866e6f25d', 7, 'O Transbordamento no Outro', NULL, '{"intro": "O encontro com Deus deve resultar no encontro com o irm\u00e3o.", "prayer": "Seja o canal por onde o amor dEle flui.", "practice": "Sirva a algu\u00e9m de forma oculta hoje.", "reflection": "A m\u00edstica que n\u00e3o serve n\u00e3o \u00e9 m\u00edstica, \u00e9 ego\u00edsmo.", "journal_prompt": "Como o seu encontro com Deus mudou o seu olhar para o outro?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('8f3f79a3-bd01-47c3-afe4-172187266e41', 'b2b2b2b2-3030-4000-8000-000000000002', 1, 'Dia 1 — Reconhecer', 'Semana 1: Acolher', '{"pch": "O Senhor est\u00e1 perto dos que t\u00eam o cora\u00e7\u00e3o quebrantado\u2026 Reconhecer a dor \u00e9 o primeiro passo.", "verse": "Sl 34,18", "lectio": "Leia Sl 34,17-22. Deus ouve o grito do justo.", "practice": "Escreva o que d\u00f3i. Sem filtro, sem julgamento.", "question": "Que dor voc\u00ea carrega em sil\u00eancio?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('7229c52f-8e64-48b4-ad8c-978f30cb3bb9', 'b2b2b2b2-3030-4000-8000-000000000002', 2, 'Dia 2 — Acolher', 'Semana 1: Acolher', '{"pch": "Vinde a mim, todos os cansados\u2026 Voc\u00ea n\u00e3o precisa ser forte o tempo todo.", "verse": "Mt 11,28", "lectio": "Leia Mt 11,25-30. O jugo suave.", "practice": "Permita-se sentir. Chore se precisar. Deus acolhe.", "question": "Quando foi a \u00faltima vez que voc\u00ea se permitiu chorar?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('228114be-1c58-4279-bd86-90f0aa69b48d', 'b2b2b2b2-3030-4000-8000-000000000002', 3, 'Dia 3 — Nomear', 'Semana 1: Acolher', '{"pch": "Onde est\u00e1s? Deus pergunta n\u00e3o porque n\u00e3o sabe\u2026 mas porque voc\u00ea precisa responder.", "verse": "Gn 3,9", "lectio": "Leia Gn 3,8-13. Ad\u00e3o se escondeu. Deus o buscou.", "practice": "Nomeie 3 emo\u00e7\u00f5es que voc\u00ea sente agora. Sem julg\u00e1-las.", "question": "Se sua dor tivesse um nome, qual seria?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('8d54eebc-3e64-4de2-b654-e644df39afdf', 'b2b2b2b2-3030-4000-8000-000000000002', 4, 'Dia 4 — Chorar', 'Semana 1: Acolher', '{"pch": "Jesus chorou. Se Deus chora, por que voc\u00ea n\u00e3o pode?", "verse": "Jo 11,35", "lectio": "Leia Jo 11,32-44. Jesus se comoveu antes de agir.", "practice": "Leia um salmo de lamento (Sl 42). Fa\u00e7a dele sua ora\u00e7\u00e3o.", "question": "Que l\u00e1grimas voc\u00ea segurou por tempo demais?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('533c65e5-95e8-4e3d-a3ef-9519036e8743', 'b2b2b2b2-3030-4000-8000-000000000002', 5, 'Dia 5 — Abandono', 'Semana 1: Acolher', '{"pch": "Ainda que meu pai e minha m\u00e3e me abandonem\u2026 o Senhor me acolher\u00e1.", "verse": "Sl 27,10", "lectio": "Leia Sl 27. Deus \u00e9 luz e salva\u00e7\u00e3o.", "practice": "Escreva uma carta ao seu eu crian\u00e7a. Diga o que ele precisava ouvir.", "question": "Quem te fez sentir abandonado?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('cf838250-8259-4ee5-8181-cc2b15a71541', 'b2b2b2b2-3030-4000-8000-000000000002', 6, 'Dia 6 — Rejeição', 'Semana 1: Acolher', '{"pch": "Desprezado e rejeitado\u2026 Jesus conhece a rejei\u00e7\u00e3o. Ele entende.", "verse": "Is 53,3", "lectio": "Leia Is 53,1-6. O servo sofredor.", "practice": "Identifique padr\u00f5es de rejei\u00e7\u00e3o na sua vida. Ore sobre cada um.", "question": "Que rejei\u00e7\u00e3o ainda ecoa dentro de voc\u00ea?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('3aef49a3-97c8-4f50-9fef-dfe888deb99d', 'b2b2b2b2-3030-4000-8000-000000000002', 7, 'Dia 7 — Descanso', 'Semana 1: Acolher', '{"pch": "Ele me faz repousar em pastos verdejantes\u2026 A cura come\u00e7a no descanso, n\u00e3o no esfor\u00e7o.", "verse": "Sl 23,2", "lectio": "Leia Sl 23. O Bom Pastor cuida.", "practice": "Tire 30 minutos hoje sem produtividade. Apenas seja.", "question": "Voc\u00ea tem descansado de verdade?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('ee9c9fe0-4f4b-4ccc-aceb-150a0ac29e43', 'b2b2b2b2-3030-4000-8000-000000000002', 8, 'Dia 8 — Raiva', 'Semana 2: Processar', '{"pch": "Irai-vos e n\u00e3o pequeis\u2026 A raiva n\u00e3o \u00e9 pecado. O que voc\u00ea faz com ela pode ser.", "verse": "Ef 4,26", "lectio": "Leia Ef 4,25-32. Falar a verdade em amor.", "practice": "Escreva uma carta de raiva (sem enviar). Depois, entregue a Deus.", "question": "De que voc\u00ea tem raiva e nunca admitiu?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('b46a74c9-a461-4059-bf94-083845914f4f', 'b2b2b2b2-3030-4000-8000-000000000002', 9, 'Dia 9 — Culpa', 'Semana 2: Processar', '{"pch": "Nenhuma condena\u00e7\u00e3o h\u00e1\u2026 para os que est\u00e3o em Cristo. A culpa que condena n\u00e3o vem de Deus.", "verse": "Rm 8,1", "lectio": "Leia Rm 8,1-4. Liberdade da condena\u00e7\u00e3o.", "practice": "Diga em voz alta: Eu sou perdoado. Eu estou livre.", "question": "Que culpa te persegue mesmo depois de ter sido perdoado?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('e85b59ed-a6af-4ddf-becc-eaea5b5d0400', 'b2b2b2b2-3030-4000-8000-000000000002', 10, 'Dia 10 — Vergonha', 'Semana 2: Processar', '{"pch": "Em vez da vergonha, por\u00e7\u00e3o dobrada\u2026 Deus troca sua vergonha por honra.", "verse": "Is 61,7", "lectio": "Leia Is 61,1-7. O Esp\u00edrito do Senhor cura.", "practice": "Compartilhe com Deus (em ora\u00e7\u00e3o) aquilo que esconde de todos.", "question": "De que voc\u00ea tem vergonha que nunca contou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('c18e4986-5cf4-45f0-8643-bad413671530', 'b2b2b2b2-3030-4000-8000-000000000002', 11, 'Dia 11 — Luto', 'Semana 2: Processar', '{"pch": "Enxugar\u00e1 toda l\u00e1grima\u2026 A dor \u00e9 tempor\u00e1ria. A consola\u00e7\u00e3o \u00e9 eterna.", "verse": "Ap 21,4", "lectio": "Leia Ap 21,1-5. O novo c\u00e9u e a nova terra.", "practice": "Escreva uma despedida para o que perdeu. Permita-se sentir.", "question": "Que perda voc\u00ea ainda n\u00e3o processou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('bc9b38b5-7633-4e61-a5aa-d6b58133c738', 'b2b2b2b2-3030-4000-8000-000000000002', 12, 'Dia 12 — Medo', 'Semana 2: Processar', '{"pch": "Deus n\u00e3o nos deu esp\u00edrito de medo\u2026 mas de poder, amor e equil\u00edbrio.", "verse": "2Tm 1,7", "lectio": "Leia 2Tm 1,6-12. Reavivar o dom de Deus.", "practice": "Enfrente um pequeno medo hoje. Celebre a vit\u00f3ria.", "question": "Que medo controla sua vida sem voc\u00ea perceber?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('43edf712-d630-4462-b3d2-8cb62fa8aa8e', 'b2b2b2b2-3030-4000-8000-000000000002', 13, 'Dia 13 — Perdoar-se', 'Semana 2: Processar', '{"pch": "Se confessarmos os nossos pecados, Ele \u00e9 fiel e justo para nos perdoar\u2026 Voc\u00ea tamb\u00e9m pode se perdoar.", "verse": "1Jo 1,9", "lectio": "Leia 1Jo 1,5-10. Andar na luz.", "practice": "Olhe no espelho e diga: Eu te perdoo. Eu te amo.", "question": "O que voc\u00ea fez que ainda n\u00e3o se perdoou?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('27d85dd7-a74c-4d01-8e0a-e90bdbbf424e', 'b2b2b2b2-3030-4000-8000-000000000002', 14, 'Dia 14 — Perdoar outros', 'Semana 2: Processar', '{"pch": "Se perdoardes\u2026 tamb\u00e9m o Pai vos perdoar\u00e1. Perdoar n\u00e3o \u00e9 esquecer \u2014 \u00e9 soltar.", "verse": "Mt 6,14", "lectio": "Leia Mt 6,12-15 e Mt 18,21-35. O servo impiedoso.", "practice": "Reze pelo nome de quem te machucou. Solte a amarra.", "question": "Quem ainda ocupa espa\u00e7o na sua dor?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
INSERT INTO public.journey_steps (id, journey_id, step_order, title, subtitle, content) VALUES ('404a407c-7d20-40d5-9662-2a11188d2e77', 'b2b2b2b2-3030-4000-8000-000000000002', 15, 'Dia 15 — Nova pele', 'Semana 3: Reconstruir', '{"pch": "Eis que farei entrar em v\u00f3s o esp\u00edrito, e vivereis\u2026 Ossos secos podem viver.", "verse": "Ez 37,5", "lectio": "Leia Ez 37,1-14. O vale dos ossos secos.", "practice": "Visualize sua vida restaurada. Escreva como seria.", "question": "Que parte de voc\u00ea precisa renascer?"}') ON CONFLICT (id) DO UPDATE SET journey_id = EXCLUDED.journey_id, step_order = EXCLUDED.step_order, title = EXCLUDED.title, subtitle = EXCLUDED.subtitle, content = EXCLUDED.content;
